edits.replacement:
#root #keyslist, #root #setlist{ padding-bottom:var(--sp-5); -webkit-mask-image:linear-gradient(to bottom, var(--ui-void) calc(100% - var(--sp-5)), transparent); mask-image:linear-gradient(to bottom, var(--ui-void) calc(100% - var(--sp-5)), transparent); }
/* v31.xx (cw-pset10) critic c-31y (Pad buttons 75 at 2: "the banner is offset (481 to 1439) from the list columns", "the scrollbar is a thin dim 4px line", "the key column leaves empty cells"; Settings 70 at 2: "the pause when the window loses focus row is 82px against 66px for the others", "the description pane touches the footer divider with no bottom padding"). Now: the rebind callout is as wide as the pad buttons table (1440) and lines up with its labels, the Settings and Keys scrollbar is 8px, every Settings row is one height (the hidden hint line no longer pads a row), and the detail strip keeps 16px above the footer hint. */
#root #keysmodal #keysnote{ max-width:calc(var(--sp-5) * 30); padding-inline:var(--sp-3); }
#root #setlist::-webkit-scrollbar, #root #keyslist::-webkit-scrollbar{ width:8px; }
#root #setlist::-webkit-scrollbar-thumb, #root #keyslist::-webkit-scrollbar-thumb{ border-radius:4px; }
#root #setlist .row:not(.setjump) > div:first-child > .hint{ display:none; }
#root #setlist .row:not(.setjump){ box-sizing:border-box; height:var(--btn-h); padding-block:0; align-items:center; }
#root #setdetail{ margin-bottom:var(--sp-2); }

check:
{v:'VER',what:'Keys callout is as wide as the table, scrollbars are 8px, Settings rows share one height',
 run:function(){
   var bad=[], kl, kn, rows, i, hs={}, ks=0, padWas=document.body.classList.contains('padon');
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     document.body.classList.remove('padon');
     keysOpen(false); kl=document.getElementById('keyslist'); kn=document.getElementById('keysnote');
     if(!kl||!kn) bad.push('no keys list or note');
     else{
       kn.className='wait'; kn.textContent='press a key for sprint';
       if(Math.abs(kn.getBoundingClientRect().width-kl.getBoundingClientRect().width)>2) bad.push('the keys note is '+Math.round(kn.getBoundingClientRect().width)+' wide against the table '+Math.round(kl.getBoundingClientRect().width));
     }
     try{ document.getElementById('keysmodal').classList.remove('on'); }catch(_k){}
     openSettings('display');
     rows=document.querySelectorAll('#setlist .row:not(.setjump)');
     if(rows.length<4) bad.push('too few settings rows');
     for(i=0;i<rows.length;i++){ if(rows[i].offsetHeight>0) hs[Math.round(rows[i].getBoundingClientRect().height)]=1; }
     for(i in hs) ks++;
     if(ks!==1) bad.push('settings rows have '+ks+' different heights: '+Object.keys(hs).join(','));
     var sl=document.getElementById('setlist'); if(sl && sl.offsetWidth-sl.clientWidth>0 && sl.offsetWidth-sl.clientWidth<8) bad.push('settings scrollbar is '+(sl.offsetWidth-sl.clientWidth)+'px');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var q=document.getElementById('settingsmodal'); if(q) q.classList.remove('on'); q=document.getElementById('keysmodal'); if(q) q.classList.remove('on'); }catch(_k){} try{ __topClear(); }catch(_c){} document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
